import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.CvydjLy7.js";const u=JSON.parse('{"title":"十三、常见问题","description":"","frontmatter":{"title":"十三、常见问题"},"headers":[],"relativePath":"ch04/13.md","filePath":"ch04/13.md","lastUpdated":1789497795000}'),c={name:"ch04/13.md"};function a(i,t,l,n,s,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="十三、常见问题" tabindex="-1">十三、常见问题 <a class="header-anchor" href="#十三、常见问题" aria-label="Permalink to &quot;十三、常见问题&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td>加了 <code>@EnableWebMvc</code> 后静态资源 404</td><td>删掉这个注解，改为实现 <code>WebMvcConfigurer</code></td></tr><tr><td><code>@RequestParam</code> 上的 <code>@Min</code> 不生效</td><td>类上漏了 <code>@Validated</code></td></tr><tr><td><code>@Valid @RequestBody</code> 不生效</td><td>注解加在了 Controller 方法上，应该加在参数上；或 DTO 是普通类但没写 getter（record 无此问题）</td></tr><tr><td>枚举传错值返回 500</td><td>补 <code>HttpMessageNotReadableException</code> 的处理分支</td></tr><tr><td>上传返回 500 而不是 413</td><td>补 <code>MaxUploadSizeExceededException</code> 的处理分支；或确认 <code>max-file-size</code> 配置生效</td></tr><tr><td>上传大文件报 1MB 超限</td><td>Spring Boot 默认上限就是 1MB，改 <code>spring.servlet.multipart.max-file-size</code></td></tr><tr><td>图片不显示、浏览器直接下载</td><td>响应少了 <code>Content-Type</code>，<code>mediaTypeOf</code> 没按后缀返回图片类型</td></tr><tr><td>后缀合法但内容不是图片</td><td>只校验了后缀，没有校验文件头魔数</td></tr><tr><td>管理端点报 <code>package does not exist</code></td><td>4.x 模块拆分导致包名迁移，见第 0 篇的包名迁移表</td></tr><tr><td>跨域报错 <code>Allow-Origin: *</code> 与凭证冲突</td><td><code>allowCredentials(true)</code> 时来源必须逐个列出</td></tr><tr><td>分页出现重复或遗漏记录</td><td>排序键不唯一，加上 <code>id</code> 作为第二排序键</td></tr><tr><td>停机时请求被中断</td><td>配 <code>server.shutdown: graceful</code>，并确认发的是 <code>SIGTERM</code> 不是 <code>SIGKILL</code></td></tr><tr><td><code>page</code> 参数前端从 1 开始传，后端从 0 开始理解</td><td>统一约定并在文档里写明；MyBatis-Plus 恰好相反，见第 6 篇</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>接口能用了，但任何人不登录就能新增和删除——这显然不能上线。第 5 篇对照官方的 Security 章节，给这套接口加上认证与授权：Spring Security 6 的过滤链配置、JWT 无状态认证、密码加密、角色与权限控制，以及前后端联调时的登录接口设计。</p></blockquote>',3)])])}const h=d(c,[["render",a]]);export{u as __pageData,h as default};
